schema:
CREATE TABLE t1 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t2 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t3 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t4 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 SMALLINT NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t1(c1)
);

CREATE TABLE t5 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t1(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

CREATE TABLE t6 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

counterexample:
INSERT INTO t1 (c1, c2) VALUES ('A', 'dummy1');

INSERT INTO t2 (c1, c2) VALUES ('Amstel', 'dummy2');

-- Insert a row into t5 with c2='Amstel' and c3=1.00 (which is not >2)
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'Amstel', 1.00);

-- Optional: Insert another row meeting both conditions to show that both queries return it
INSERT INTO t1 (c1, c2) VALUES ('B', 'dummy3');

INSERT INTO t2 (c1, c2) VALUES ('Corona', 'dummy4');

INSERT INTO t5 (c1, c2, c3) VALUES ('B', 'Corona', 3.00);

