counterexample:
-- Insert into t1. We need two rows: one for the t4.c2 value and one for t5.c1
INSERT INTO t1 (c1, c2) VALUES ('Corona', 'val1');
INSERT INTO t1 (c1, c2) VALUES ('A', 'valA');

-- Insert a row into t2 for t5.c2 (which is 'Corona')
INSERT INTO t2 (c1, c2) VALUES ('Corona', 'val2');

-- Insert into t3 for t4.c1 (which is 'A')
INSERT INTO t3 (c1, c2) VALUES ('A', 'dummy');

-- Insert into t4 with c1 = 'A' and c2 = 'Corona'
INSERT INTO t4 (c1, c2, c3) VALUES ('A', 'Corona', 1);

-- Insert into t5 with c1 = 'A' and c2 = 'Corona'
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'Corona', 1.00);

-- Do NOT insert any t6 row for c1 = 'A' with c2 = 'Corona'.
-- (Optionally, you could insert unrelated rows in t6, but they would not affect the test case.)

