CREATE TABLE t1 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t2 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t3 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t4 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 SMALLINT NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t1(c1)
);

CREATE TABLE t5 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t1(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

CREATE TABLE t6 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

counterexample:
-- Insert supporting rows for the foreign key constraints

-- t1: Required for t4.c2 and t5.c1
INSERT INTO t1(c1, c2) VALUES ('A', 'dummyA');
INSERT INTO t1(c1, c2) VALUES ('Corona', 'dummyCorona');

-- t2: Required for t5.c2 and t6.c2
INSERT INTO t2(c1, c2) VALUES ('Corona', 'dummyCorona');

-- t3: Required for t4.c1 and t6.c1
INSERT INTO t3(c1, c2) VALUES ('A', 'dummyA');

-- t4: Row that joins with t5 and has c2 = 'Corona'
INSERT INTO t4(c1, c2, c3) VALUES ('A', 'Corona', 1);

-- t5: Row that joins with t4 and has c1 = 'A' and c2 = 'Corona'
INSERT INTO t5(c1, c2, c3) VALUES ('A', 'Corona', 1.00);

-- t6: Row that causes divergence; since it has (c1, c2) = ('A', 'Corona'),
-- Q2 will return 'A' (because 'A' is IN the subquery), while Q1 will exclude it (because 'A' is NOT IN condition fails).
INSERT INTO t6(c1, c2) VALUES ('A', 'Corona');

