INSERT INTO t2 (c1) VALUES ('Spain');

-- For table t3 (PK c1); t4 and t6 reference t3
INSERT INTO t3 (c1) VALUES ('A');
INSERT INTO t3 (c1) VALUES ('B');

-- Now, insert rows for t4: candidate 'A' appears in t4 with c2 = 'Corona'
INSERT INTO t4 (c1, c2, c3) VALUES ('A', 'Corona', 1);

-- Insert rows for t5: to join with t4 via NATURAL JOIN, t5 must have the same values for c1 and c2
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'Corona', 3.14);

-- Finally, for t6: add a row for candidate 'B' with c2 = 'Spain'. Note candidate 'B' does not have any row with c2 = 'Corona', so it qualifies in Q2.
INSERT INTO t6 (c1, c2) VALUES ('B', 'Spain');

