counterexample:
-- Insert necessary rows for foreign key dependencies

-- t3 is referenced by t4.c1
INSERT INTO t3 (c1, c2) VALUES ('A', 'a');
INSERT INTO t3 (c1, c2) VALUES ('B', 'b');
INSERT INTO t3 (c1, c2) VALUES ('C', 'c');

-- t1 is referenced by t4.c2. We need to insert a row for each distinct value in t4.c2 below
INSERT INTO t1 (c1, c2) VALUES ('p', 'p_desc');
INSERT INTO t1 (c1, c2) VALUES ('q', 'q_desc');
INSERT INTO t1 (c1, c2) VALUES ('r', 'r_desc');

-- Now, insert rows into t4
-- Group A: c1 = 'A' with two rows; sum(c3) = 1 + 2 = 3, count = 2
INSERT INTO t4 (c1, c2, c3) VALUES ('A', 'p', 1);
INSERT INTO t4 (c1, c2, c3) VALUES ('A', 'q', 2);

-- Group B: c1 = 'B' with three rows; sum(c3) = 1 + 1 + 1 = 3, count = 3
INSERT INTO t4 (c1, c2, c3) VALUES ('B', 'p', 1);
INSERT INTO t4 (c1, c2, c3) VALUES ('B', 'q', 1);
INSERT INTO t4 (c1, c2, c3) VALUES ('B', 'r', 1);

-- Group C: c1 = 'C' with one row; sum(c3) = 2, count = 1
INSERT INTO t4 (c1, c2, c3) VALUES ('C', 'p', 2);

