INSERT INTO t4 (c1, c2, c3) VALUES ('A', 'T2', 1);

-- t5: corresponding join rows
INSERT INTO t5 (c1, c2, c3) VALUES ('T1', 'X', 10.00);  -- good, as 'X' will be in t6 for 'A'
INSERT INTO t5 (c1, c2, c3) VALUES ('T2', 'Y', 20.00);  -- bad, as 'Y' is not in t6 for 'A'

-- t6: allowed value only includes 'X' for t3 row 'A'
INSERT INTO t6 (c1, c2) VALUES ('A', 'X');

