-- Insert a t5 row that does not qualify: c2 is 'Amstel' but c3 is not > 2
INSERT INTO t5 (c1, c2, c3) VALUES ('x', 'Amstel', 2.00);

-- Leave t4 and t6 empty so that the subquery in Q1 returns no rows.

