INSERT INTO t3 (c1, c2) VALUES ('B2', 'dummyB2');

-- Insert rows into t4 so that the join in Q1 can occur
-- For the t5 row with c1 = 'A', we need t4.f.c2 = 'A' and f.c1 LIKE 'B%'
INSERT INTO t4 (c1, c2, c3) VALUES ('B1', 'A', 10);
-- For the t5 row with c1 = 'C', we need t4.f.c2 = 'C' and f.c1 LIKE 'B%'
INSERT INTO t4 (c1, c2, c3) VALUES ('B2', 'C', 20);

-- Insert rows into t5; these will form one group based on c2 = 'X'
-- Their different c1 values allow Q1's subquery to count two distinct s.c1 values via the join
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'X', 100.00);
INSERT INTO t5 (c1, c2, c3) VALUES ('C', 'X', 200.00);

