INSERT INTO t4 (c1, c2, c3) VALUES ('B1', 'A2', 10);

-- Insert data for table t5. t5.c1 references t1 and t5.c2 references t2. We create two rows with the same t5.c2 ('X') but with different t5.c1 ('A1' and 'A2').
INSERT INTO t5 (c1, c2, c3) VALUES ('A1', 'X', 100.00);
INSERT INTO t5 (c1, c2, c3) VALUES ('A2', 'X', 200.00);

