counterexample:
-- Insert rows for t1; note that t1.c1 is referenced by t5 and t4
INSERT INTO t1 (c1, c2) VALUES ('X1', 'dummy1');
INSERT INTO t1 (c1, c2) VALUES ('X2', 'dummy2');
INSERT INTO t1 (c1, c2) VALUES ('B1', 'dummyB');

-- Insert row for t2; t5.c2 references t2(c1)
INSERT INTO t2 (c1, c2) VALUES ('G1', 'dummyG');

-- Insert rows for t3; t4.c1 references t3(c1)
INSERT INTO t3 (c1, c2) VALUES ('X1', 'dummy3');
INSERT INTO t3 (c1, c2) VALUES ('X2', 'dummy4');

-- Insert rows for t4; note f.c2 must start with 'B' and must exist in t1
INSERT INTO t4 (c1, c2, c3) VALUES ('X1', 'B1', 10);
INSERT INTO t4 (c1, c2, c3) VALUES ('X2', 'B1', 20);

-- Insert rows for t5; note t5.c1 references t1 and t5.c2 references t2
-- Both rows have the same c3 value to fail Q2's HAVING count(DISTINCT c3) condition
INSERT INTO t5 (c1, c2, c3) VALUES ('X1', 'G1', 100.00);
INSERT INTO t5 (c1, c2, c3) VALUES ('X2', 'G1', 100.00);

