counterexample:
-- Insert data into t1
INSERT INTO t1 (c1, c2) VALUES ('A', 'valA');
INSERT INTO t1 (c1, c2) VALUES ('B', 'valB');

-- Insert corresponding data into t2, since t5 references t2(c1)
