INSERT INTO t4 (c1, c2, c3) VALUES ('Y', 'A', 20);

-- t2 must have a row so that t5.c2 (a foreign key) exists; here we use 'P'.
INSERT INTO t2 (c1, c2) VALUES ('P', 'dummy');

-- Insert a row into t5. t5.c1 references t1(c1) so we use 'A'. Also, t5.c2 references t2(c1) so we use 'P'.
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'P', 5.00);

