counterexample:
-- Insert rows into t1
INSERT INTO t1 (c1, c2) VALUES ('A', 'foo');
INSERT INTO t1 (c1, c2) VALUES ('B', 'bar');

-- t2: required by t5 foreign key on c2
INSERT INTO t2 (c1, c2) VALUES ('X', 'x_value');
INSERT INTO t2 (c1, c2) VALUES ('B', 'b_value');

-- t3: required for t4 foreign key on c1
INSERT INTO t3 (c1, c2) VALUES ('a1', 't3_for_a1');
INSERT INTO t3 (c1, c2) VALUES ('d1', 't3_for_d1');
INSERT INTO t3 (c1, c2) VALUES ('d2', 't3_for_d2');

-- t4: For row 'A' and two rows for 'B' (to affect subquery ordering)
-- For t1 = 'A', one t4 row
INSERT INTO t4 (c1, c2, c3) VALUES ('a1', 'A', 5);
-- For t1 = 'B', two t4 rows with different c3 values
INSERT INTO t4 (c1, c2, c3) VALUES ('d1', 'B', 20);
INSERT INTO t4 (c1, c2, c3) VALUES ('d2', 'B', 10);

-- t5: Create a row for 'A' that joins in Q1 (since Q1 joins on t5.c1) but does NOT join in Q2 (Q2 requires t5.c2 = t1.c1)
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'X', 2.00);

-- t5: Create a row for 'B' that joins in both queries (t5.c1 = 'B' joins Q1 and t5.c2 = 'B' joins Q2)
INSERT INTO t5 (c1, c2, c3) VALUES ('B', 'B', 3.14);

