INSERT INTO t4 (c1, c2, c3) VALUES ('Y', 'A', 5);

/* Insert t5 row linked to t1 'A'. In t5, (c1, c2) is the primary key and c1 references t1, while c2 references t2. */
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'B', 100.00);

