-- Insert records for t1
INSERT INTO t1 (c1, c2) VALUES ('A', 'a_info');
INSERT INTO t1 (c1, c2) VALUES ('B', 'b_info');

-- t2 is referenced by t5 (foreign key on t2.c1), so we need a matching t2 row
INSERT INTO t2 (c1, c2) VALUES ('T2', 't2_info');

-- t3 is referenced by t4 (foreign key on t3.c1)
INSERT INTO t3 (c1, c2) VALUES ('X', 'x_info');
INSERT INTO t3 (c1, c2) VALUES ('Y', 'y_info');

-- Insert records for t4. Only t1 row 'B' will be referenced here via t4.c2.
-- Two records for 'B' with different c3 values to test the ordering logic for most_reg_drinker.
INSERT INTO t4 (c1, c2, c3) VALUES ('X', 'B', 10);
INSERT INTO t4 (c1, c2, c3) VALUES ('Y', 'B', 5);

-- Insert record for t5. Only t1 row 'B' gets a t5 record. t5.c2 must exist in t2.
INSERT INTO t5 (c1, c2, c3) VALUES ('B', 'T2', 20.00);

