-- Insert into t1: a single bar
INSERT INTO t1 (c1, c2) VALUES ('bar1', 'some_bar_info');

-- Insert into t3: drinkers for t4 (t4.c1 references t3.c1)
INSERT INTO t3 (c1, c2) VALUES ('drinker1', 'dummy');
INSERT INTO t3 (c1, c2) VALUES ('drinker2', 'dummy');

-- Insert into t4: two rows for bar1 with different c3 values
INSERT INTO t4 (c1, c2, c3) VALUES ('drinker1', 'bar1', 1);
INSERT INTO t4 (c1, c2, c3) VALUES ('drinker2', 'bar1', 2);

-- Insert into t2: a referenced row for t5
INSERT INTO t2 (c1, c2) VALUES ('t2rec1', 'dummy');

-- Insert into t5: one entry for bar1 so that avg_price is not NULL
INSERT INTO t5 (c1, c2, c3) VALUES ('bar1', 't2rec1', 10.00);

