counterexample:
INSERT INTO t1 (c1, c2) VALUES ('A', 'dummy');

-- t3 is referenced by t4; we need rows for drinkers 'a' and 'b'
INSERT INTO t3 (c1, c2) VALUES ('a', 'dummyT3');
INSERT INTO t3 (c1, c2) VALUES ('b', 'dummyT3');

-- Insert two t4 rows for t1 record 'A': one with the highest c3, and one with a lower c3 but with a smaller c1
INSERT INTO t4 (c1, c2, c3) VALUES ('b', 'A', 10);
INSERT INTO t4 (c1, c2, c3) VALUES ('a', 'A', 9);

-- For t5, we insert one row to supply an average price for t1 'A'.
-- t5 references t2 as well, so we need a matching t2 row.
INSERT INTO t2 (c1, c2) VALUES ('T2_x', 'dummy');
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'T2_x', 5.00);

