-- t2: list of beers (the referenced table for t5.c2)
INSERT INTO t2 (c1, c2) VALUES ('A','Beer A');

-- t5: price offers. Note that for beer A the minimum price is 2.00. Two rows offer that price, while one row offers a higher price (3.00).
INSERT INTO t5 (c1, c2, c3) VALUES ('S1', 'A', 2.00);
INSERT INTO t5 (c1, c2, c3) VALUES ('S2', 'A', 2.00);
INSERT INTO t5 (c1, c2, c3) VALUES ('S3', 'A', 3.00);

